CREATE TYPE risk_rule_status AS ENUM ('DRAFT','PUBLISHED'); CREATE TYPE microbiological_risk AS ENUM ('LOW','MEDIUM','HIGH'); CREATE TYPE inspection_frequency AS ENUM ('ANNUAL','SEMIANNUAL','QUARTERLY');
CREATE TABLE risk_rule_sets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code varchar(80) NOT NULL UNIQUE,name varchar(200) NOT NULL,current_published_version_id uuid,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(btrim(code)<>'' AND code=upper(btrim(code))),CHECK(btrim(name)<>''));
CREATE TABLE risk_rule_versions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),risk_rule_set_id uuid NOT NULL REFERENCES risk_rule_sets(id) ON DELETE RESTRICT,version_number integer NOT NULL CHECK(version_number>0),status risk_rule_status NOT NULL DEFAULT 'DRAFT',publication_note text,published_at timestamptz,published_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(risk_rule_set_id,version_number),CHECK((status='DRAFT' AND published_at IS NULL AND published_by_user_id IS NULL) OR (status='PUBLISHED' AND published_at IS NOT NULL AND published_by_user_id IS NOT NULL)));
ALTER TABLE risk_rule_sets ADD CONSTRAINT risk_rule_sets_current_fk FOREIGN KEY(current_published_version_id) REFERENCES risk_rule_versions(id) ON DELETE RESTRICT;
CREATE TABLE risk_factors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),risk_rule_version_id uuid NOT NULL REFERENCES risk_rule_versions(id) ON DELETE RESTRICT,code varchar(80) NOT NULL,name varchar(160) NOT NULL,weight numeric(6,4) NOT NULL,sort_order integer NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(risk_rule_version_id,code),UNIQUE(risk_rule_version_id,sort_order),CHECK(code=upper(btrim(code)) AND btrim(code)<>''),CHECK(btrim(name)<>''),CHECK(weight>0 AND weight<=1),CHECK(sort_order>=0));
CREATE TABLE risk_factor_options(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),risk_factor_id uuid NOT NULL REFERENCES risk_factors(id) ON DELETE RESTRICT,code varchar(80) NOT NULL,label varchar(300) NOT NULL,score numeric(4,2) NOT NULL,sort_order integer NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(risk_factor_id,code),UNIQUE(risk_factor_id,score),UNIQUE(risk_factor_id,sort_order),CHECK(code=upper(btrim(code)) AND btrim(code)<>''),CHECK(btrim(label)<>''),CHECK(score IN(1.00,1.67,2.33,3.00)),CHECK(sort_order>=0));
CREATE TABLE food_risk_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),risk_rule_version_id uuid NOT NULL REFERENCES risk_rule_versions(id) ON DELETE RESTRICT,code varchar(120) NOT NULL,name varchar(300) NOT NULL,sort_order integer NOT NULL DEFAULT 0,source_file varchar(300),source_sheet varchar(160),source_row_number integer,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(risk_rule_version_id,code),CHECK(code=upper(btrim(code)) AND btrim(code)<>''),CHECK(btrim(name)<>''),CHECK(sort_order>=0));
CREATE TABLE food_risk_subcategories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),category_id uuid NOT NULL REFERENCES food_risk_categories(id) ON DELETE RESTRICT,name varchar(700) NOT NULL,microbiological_risk microbiological_risk,risk_score smallint,sort_order integer NOT NULL DEFAULT 0,source_file varchar(300),source_sheet varchar(160),source_row_number integer,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(category_id,name),CHECK(btrim(name)<>''),CHECK(sort_order>=0),CHECK((microbiological_risk IS NULL AND risk_score IS NULL) OR (microbiological_risk='LOW' AND risk_score=1) OR (microbiological_risk='MEDIUM' AND risk_score=2) OR (microbiological_risk='HIGH' AND risk_score=3)));
CREATE TABLE inspection_frequency_ranges(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),risk_rule_version_id uuid NOT NULL REFERENCES risk_rule_versions(id) ON DELETE RESTRICT,lower_bound numeric(8,2) NOT NULL,upper_bound numeric(8,2),lower_inclusive boolean NOT NULL,upper_inclusive boolean NOT NULL DEFAULT false,frequency inspection_frequency NOT NULL,label varchar(100) NOT NULL,sort_order integer NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(lower_bound>=0),CHECK(upper_bound IS NULL OR upper_bound>lower_bound),CHECK(upper_bound IS NOT NULL OR upper_inclusive=false),CHECK(btrim(label)<>''),UNIQUE(risk_rule_version_id,sort_order),EXCLUDE USING gist(risk_rule_version_id WITH =,numrange(lower_bound,upper_bound,CASE WHEN lower_inclusive AND upper_inclusive THEN '[]' WHEN lower_inclusive THEN '[)' WHEN upper_inclusive THEN '(]' ELSE '()' END) WITH &&));
CREATE OR REPLACE FUNCTION risk_version_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' AND OLD.status='PUBLISHED' THEN RAISE EXCEPTION 'published risk version immutable'; END IF; IF TG_OP='UPDATE' THEN IF OLD.status='PUBLISHED' THEN RAISE EXCEPTION 'published risk version immutable'; END IF; IF NEW.status='PUBLISHED' THEN IF NEW.risk_rule_set_id IS DISTINCT FROM OLD.risk_rule_set_id OR NEW.version_number IS DISTINCT FROM OLD.version_number THEN RAISE EXCEPTION 'invalid publication'; END IF; IF (SELECT count(*) FROM risk_factors WHERE risk_rule_version_id=NEW.id)<>6 OR (SELECT array_agg(code ORDER BY code) FROM risk_factors WHERE risk_rule_version_id=NEW.id)<>ARRAY['BPM','HACCP','INABIE','REJECTIONS','SAMPLING','VOLUME'] OR (SELECT sum(weight) FROM risk_factors WHERE risk_rule_version_id=NEW.id)<>1.0000 THEN RAISE EXCEPTION 'invalid factors'; END IF; IF EXISTS(SELECT 1 FROM risk_factors f WHERE f.risk_rule_version_id=NEW.id AND (SELECT array_agg(score ORDER BY score) FROM risk_factor_options WHERE risk_factor_id=f.id)<>ARRAY[1.00::numeric,1.67::numeric,2.33::numeric,3.00::numeric]) THEN RAISE EXCEPTION 'invalid options'; END IF; END IF; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION risk_child_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE vid uuid; x uuid; row_data jsonb; BEGIN row_data:=to_jsonb(COALESCE(NEW,OLD)); IF TG_TABLE_NAME IN ('risk_factors','food_risk_categories','inspection_frequency_ranges') THEN vid:=(row_data->>'risk_rule_version_id')::uuid; ELSIF TG_TABLE_NAME='risk_factor_options' THEN x:=(row_data->>'risk_factor_id')::uuid; SELECT risk_rule_version_id INTO vid FROM risk_factors WHERE id=x; ELSE x:=(row_data->>'category_id')::uuid; SELECT risk_rule_version_id INTO vid FROM food_risk_categories WHERE id=x; END IF; IF EXISTS(SELECT 1 FROM risk_rule_versions WHERE id=vid AND status='PUBLISHED') THEN RAISE EXCEPTION 'published risk data immutable'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER risk_versions_guard BEFORE UPDATE OR DELETE ON risk_rule_versions FOR EACH ROW EXECUTE FUNCTION risk_version_guard();
CREATE TRIGGER risk_factors_guard BEFORE INSERT OR UPDATE OR DELETE ON risk_factors FOR EACH ROW EXECUTE FUNCTION risk_child_guard(); CREATE TRIGGER risk_options_guard BEFORE INSERT OR UPDATE OR DELETE ON risk_factor_options FOR EACH ROW EXECUTE FUNCTION risk_child_guard(); CREATE TRIGGER food_categories_guard BEFORE INSERT OR UPDATE OR DELETE ON food_risk_categories FOR EACH ROW EXECUTE FUNCTION risk_child_guard(); CREATE TRIGGER food_subcategories_guard BEFORE INSERT OR UPDATE OR DELETE ON food_risk_subcategories FOR EACH ROW EXECUTE FUNCTION risk_child_guard(); CREATE TRIGGER frequency_ranges_guard BEFORE INSERT OR UPDATE OR DELETE ON inspection_frequency_ranges FOR EACH ROW EXECUTE FUNCTION risk_child_guard();
